import{_ as t,o,c as e,ag as n}from"./chunks/framework.D5hoimZQ.js";const p=JSON.parse('{"title":"🔬 科学快报 | 2026年9月2日（事后重建版）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"science-log/src/reconstructed/2026-09-02.md","filePath":"science-log/src/reconstructed/2026-09-02.md"}'),s={name:"science-log/src/reconstructed/2026-09-02.md"};function a(g,r,i,c,l,d){return o(),e("div",null,[...r[0]||(r[0]=[n('<h1 id="🔬-科学快报-2026年9月2日-事后重建版" tabindex="-1">🔬 科学快报 | 2026年9月2日（事后重建版） <a class="header-anchor" href="#🔬-科学快报-2026年9月2日-事后重建版" aria-label="Permalink to &quot;🔬 科学快报 | 2026年9月2日（事后重建版）&quot;">​</a></h1><blockquote><p>⚠️ <strong>事后重建版</strong>：本文件<strong>不是</strong>当日发布原文。由 2026-11-05 依 arXiv / CrossRef <strong>按发布日期回溯检索</strong>生成，选题与排序均为事后判定，<strong>不代表历史原貌</strong>。 说明：2026-09-02 为<strong>周三</strong>（工作日，期刊正常刊出），但 ScienceDaily 仓库当日<strong>无简讯文件</strong>，故按发布日期回溯重建。CrossRef 当日命中：Nature（0028-0836）39 条，其中 <strong><code>10.1038/s41586-…</code> 研究论文 21 条</strong>（其余为 <code>d41586</code> 新闻 / Author Correction / Retraction Note，已剔除）；Science 系（10.1126）11 条，多为 Science Translational Medicine 与新闻稿，研究论文偏少；PNAS（0027-8424）17 条。科学 5 篇取 Nature ×4 + PNAS ×1；AI 5 篇取自当日 arXiv cs.AI 提交（submittedDate <code>[202609020000 TO 202609022359]</code> 命中达 max_results 上限 30 篇）。期号因当日原本无刊期，标为 <code>（第 ? 期 · 事后重建版）</code>。 取证：CrossRef（Nature 0028-0836 / Science 10.1126 / PNAS 0027-8424）+ arXiv 日期区间 <code>[202609020000 TO 202609022359]</code>（cs.AI）｜ 重建日：2026-11-05</p></blockquote><h2 id="🔬-科学前沿" tabindex="-1">🔬 科学前沿 <a class="header-anchor" href="#🔬-科学前沿" aria-label="Permalink to &quot;🔬 科学前沿&quot;">​</a></h2><h3 id="🐭-晚年才开始用司美格鲁肽-仍能减缓雌鼠衰老并延长寿命" tabindex="-1">🐭 晚年才开始用司美格鲁肽，仍能减缓雌鼠衰老并延长寿命 <a class="header-anchor" href="#🐭-晚年才开始用司美格鲁肽-仍能减缓雌鼠衰老并延长寿命" aria-label="Permalink to &quot;🐭 晚年才开始用司美格鲁肽，仍能减缓雌鼠衰老并延长寿命&quot;">​</a></h3><p><strong>Late-life semaglutide treatment slows ageing and extends lifespan in female mice</strong><em>Nature（2026-09-02）</em></p><p>GLP-1 受体激动剂长期被视作降糖减重药物，但其「多效性」背后的机制一直不清。Yufan Feng 等（11 位作者）给 <strong>20 月龄</strong>（相当于人类中老年）的雌性 C57BL/6 小鼠连续 <strong>3 个月</strong>给药<strong>司美格鲁肽</strong>，发现小鼠生理功能改善、衰老标志物（hallmarks of ageing）减轻，营养感应通路与保守的衰老遗传调控因子被重新调制。<strong>继续给药可延长寿命</strong>，且这些效应与<strong>热量限制</strong>（caloric restriction）这一经典延寿干预的关键特征高度平行。这提示 GLP-1 类药物可能不止作用于代谢，而是触及了衰老的核心调控网络。</p><p>📎 DOI: <a href="https://doi.org/10.1038/s41586-026-10940-7" target="_blank" rel="noreferrer">10.1038/s41586-026-10940-7</a></p><h3 id="🦠-猴痘病毒「复制体」首次被解析-聚合酶与解旋酶—引物酶如何组装" tabindex="-1">🦠 猴痘病毒「复制体」首次被解析：聚合酶与解旋酶—引物酶如何组装 <a class="header-anchor" href="#🦠-猴痘病毒「复制体」首次被解析-聚合酶与解旋酶—引物酶如何组装" aria-label="Permalink to &quot;🦠 猴痘病毒「复制体」首次被解析：聚合酶与解旋酶—引物酶如何组装&quot;">​</a></h3><p><strong>Structure and operating principles of a monkeypox virus replisome</strong><em>Nature（2026-09-02）</em></p><p>猴痘病毒（MPXV）已两次被 WHO 宣布为国际关注的突发公共卫生事件，但其基因组复制机器如何组装一直不明。痘病毒聚合酶由三个亚基组成——催化亚基 <strong>F8</strong> 与异二聚体持续因子 <strong>A22/E4</strong>；复制起始还必须与六聚体<strong>解旋酶—引物酶 E5</strong> 协同。此前 E5 与聚合酶<strong>各自</strong>的结构虽已解析，但二者<strong>如何在功能上装配成复制体</strong>仍是空白；且分离态 E5 处于<strong>自抑制构象</strong>。Zishuo Yu 等（9 位作者）解析了装配态复制体的结构，给出其<strong>运作原理</strong>，为抗痘病毒药物（如靶向复制起始）提供了结构基础。</p><p>📎 DOI: <a href="https://doi.org/10.1038/s41586-026-10937-2" target="_blank" rel="noreferrer">10.1038/s41586-026-10937-2</a></p><h3 id="🧬-把核糖体「改写」成只翻译自己-rna-上的蛋白——ribo-m-与-rna-世界难题" tabindex="-1">🧬 把核糖体「改写」成只翻译自己 RNA 上的蛋白——Ribo-M 与 RNA 世界难题 <a class="header-anchor" href="#🧬-把核糖体「改写」成只翻译自己-rna-上的蛋白——ribo-m-与-rna-世界难题" aria-label="Permalink to &quot;🧬 把核糖体「改写」成只翻译自己 RNA 上的蛋白——Ribo-M 与 RNA 世界难题&quot;">​</a></h3><p><strong>Rewiring the ribosome to translate proteins encoded in its own RNA</strong><em>Nature（2026-09-02）</em></p><p>细胞蛋白合成依赖核糖体与 mRNA 的<strong>随机碰撞</strong>，这让「为单一蛋白产量而优化翻译机器」变得困难——而这恰是生物制造的关键需求。一个可能的解法是<strong>把编码序列嵌进核糖体自身</strong>，让核糖体「专职」合成一条多肽；这同时触及 <strong>RNA 世界</strong>模型的一个长期难题：早期蛋白合成在组分稀缺、无序的情况下如何可靠运转？Kasra Alizadeh、Dorota Klepacki、Nora Vázquez-Laslop、Alexander S. Mankin（4 位作者）证明<strong>细菌核糖体确实能翻译编码在其自身 RNA 中的蛋白</strong>：他们把一段蛋白编码序列接到 <strong>16S rRNA</strong> 上，构建<strong>嵌合的信使—核糖体 RNA（mrRNA）</strong>；该杂合 mrRNA 组装成小亚基、与大亚基结合形成 <strong>Ribo-M</strong>，可翻译 mrRNA 编码的蛋白。<strong>凡破坏小亚基功能的突变或抗生素都能废止翻译</strong>，反证翻译确由这一杂合核糖体执行。</p><p>📎 DOI: <a href="https://doi.org/10.1038/s41586-026-10962-1" target="_blank" rel="noreferrer">10.1038/s41586-026-10962-1</a></p><h3 id="🌫️-1999–2006-年大气甲烷「平台期」之谜-nox-排放上升与南移推高-oh" tabindex="-1">🌫️ 1999–2006 年大气甲烷「平台期」之谜：NOx 排放上升与南移推高 OH <a class="header-anchor" href="#🌫️-1999–2006-年大气甲烷「平台期」之谜-nox-排放上升与南移推高-oh" aria-label="Permalink to &quot;🌫️ 1999–2006 年大气甲烷「平台期」之谜：NOx 排放上升与南移推高 OH&quot;">​</a></h3><p><strong>Atmospheric CH4 plateau sustained by NOx emission rise and southward shift</strong><em>Nature（2026-09-02）</em></p><p>大气甲烷增速存在<strong>十年尺度波动</strong>：1990 年代增速放缓，2000 年代经济扩张本应推高人为排放，但<strong>全球监测网在 1999–2006 年几乎没测到甲烷增长</strong>——即所谓「甲烷平台期」，成因长期不确定。Yu Zhu、Lu Shen、Gang Liu、Kelvin H. Bates、Yuxin Cai、Shushi Peng（6 位作者）<strong>结合模式模拟与甲烷/同位素观测</strong>，把平台期归因于 2000–2006 年相对 1999 年<strong>羟基自由基（OH）上升 1.4 ± 0.4%</strong>，且主要发生在<strong>热带</strong>。而热带 OH 增强<strong>主要源于氮氧化物（NOx）排放的全球上升与空间再分布</strong>——向发展中地区与海洋转移，其推手是新兴经济体的增长。这意味着甲烷的「消失」不由其自身排放决定，而由<strong>决定其寿命的氧化剂 OH</strong> 的分布决定。</p><p>📎 DOI: <a href="https://doi.org/10.1038/s41586-026-10983-w" target="_blank" rel="noreferrer">10.1038/s41586-026-10983-w</a></p><h3 id="🐸-青蛙用「脑源性酮体」让神经活动脱离葡萄糖运转" tabindex="-1">🐸 青蛙用「脑源性酮体」让神经活动脱离葡萄糖运转 <a class="header-anchor" href="#🐸-青蛙用「脑源性酮体」让神经活动脱离葡萄糖运转" aria-label="Permalink to &quot;🐸 青蛙用「脑源性酮体」让神经活动脱离葡萄糖运转&quot;">​</a></h3><p><strong>Transforming neural activity to operate without glucose metabolism using brain-derived ketone bodies</strong><em>PNAS（2026-09-02）</em></p><p>脊椎动物大脑对<strong>葡萄糖供应中断极其敏感</strong>，供糖失败即导致神经功能障碍——这几乎是一条铁律。Hafsa Yaseen、Karissa Cisneros、Rebecca Wright、Nikolaus Bueschke、Joseph M. Santin（5 位作者）却发现一个<strong>例外</strong>：青蛙的神经回路可以<strong>停止代谢葡萄糖</strong>，部分改用<strong>完全在脑内合成的酮体</strong>——这一转变发生在<strong>冬眠结束</strong>之后。机制上，酮体由<strong>星形胶质细胞合成并转运给神经元</strong>，为突触传递供能，同时伴随<strong>脂肪酸分解与酮体转运相关基因表达上调</strong>。脑源性酮体还能<strong>阻止缺氧时的活动衰减</strong>。这为理解青蛙如何在水下冬眠数月、并面对严重缺氧后<strong>重启脑回路</strong>提供了机制线索。</p><p>📎 DOI: <a href="https://doi.org/10.1073/pnas.2613981123" target="_blank" rel="noreferrer">10.1073/pnas.2613981123</a></p>',23)])])}const u=t(s,[["render",a]]);export{p as __pageData,u as default};
